-- GENERATED BY iArch. DO NOT EDIT. Change settings in iArch Settings.
-- Source: data/design/startup.json, verified against Hyprland v0.57.2. Required by
-- .config/hypr/hyprland.lua; every variable and every command below has a reason
-- recorded there, and nothing is emitted that is not.
-- Edit the record, then run python3 iarch/cli/gen_startup_lua.py --write-repo-default.

-- Session environment, exported at parse time. hl.env's third argument is upstream's
-- own export into the systemd user environment and the dbus activation environment,
-- queued as an exec-once on the first parse (LuaBindingsConfigRules.cpp:531-541).
hl.env("XDG_CURRENT_DESKTOP", "Hyprland", true)
hl.env("XDG_SESSION_TYPE", "wayland", true)
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_AUTO_SCREEN_SCALE_FACTOR", "1")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "wayland")

-- Commands the session starts once, when the compositor reports hyprland.start. Each
-- runs as /bin/sh -c in a forked child with its output discarded
-- (Executor.cpp:173-213), so shell operators work and a failure is invisible:
-- scripts/iarch-healthcheck.sh is what reports a service that did not come up.
local exec_once = {
    "/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1 || /usr/libexec/polkit-gnome-authentication-agent-1",
    "gnome-keyring-daemon --start --components=secrets",
    -- This is a command whose failure is invisible: the executor discards output
    -- and status. A session with no portal shows up as a screen share that finds
    -- nothing, which is what scripts/iarch-healthcheck.sh reports on rather than
    -- what this file can.
    "systemctl --user start --ignore-dependencies xdg-desktop-portal-hyprland.service xdg-desktop-portal.service",
    -- Replaces the v4 startup line at legacy/config/hypr/startup.conf:3, which
    -- started the shell through quickshell's own binary and a -c flag rather than
    -- the packaged command.
    "noctalia",
    "wl-clip-persist --clipboard regular",
    "sleep 3 && easyeffects --gapplication-service",
    -- Moved out of a list it did not belong in: the v5 file kept this pair inside a
    -- list gated by an NVIDIA flag, next to the vendor variables, so a default
    -- install never ran it. It has nothing to do with a GPU: it is what makes a
    -- dbus-activated application able to find the display.
    "systemctl --user import-environment WAYLAND_DISPLAY && hash dbus-update-activation-environment 2>/dev/null && dbus-update-activation-environment --systemd WAYLAND_DISPLAY",
}

-- Optional nvidia environment, off unless an installer was asked for it:
-- install.sh:1047-1049 and fedora_install.sh:845-847 flip the next line, and nothing
-- else may.
local enable_nvidia_optional = false

if enable_nvidia_optional then
    hl.env("WLR_NO_HARDWARE_CURSORS", "1")
    hl.env("LIBVA_DRIVER_NAME", "nvidia")
    hl.env("GBM_BACKEND", "nvidia-drm")
    hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
    hl.env("NVD_BACKEND", "direct")
end

hl.on("hyprland.start", function()
    for _, cmd in ipairs(exec_once) do
        hl.exec_cmd(cmd)
    end
end)

-- Removed: hl.exec_cmd([[bash -lc 'sleep 2; hyprctl reload']]) at the end of the
-- hyprland.start handler (legacy/config/hypr/startup.conf:4). The reason, and what it
-- cost, is in data/design/startup.json under removed.

return true
